Here's the Quick Start section for the strawpoll API:

```typescript
// Retrieve the tracking configuration for a specific ID.
async function getTrackingConfig(trackingConfigId: string) {
  try {
    const config = await client.getApiSiteTrackingConfigTrackingConfigId({ trackingConfigId });
    console.log("Tracking Configuration:", config);
    return config;
  } catch (error) {
    console.error("Error retrieving tracking config:", error);
    return null;
  }
}
```

```typescript
// Record a user's interaction with a strawpoll.
async function trackUserInteraction(pollId: string, vote: string) {
  try {
    const response = await client.postApiTrack({
      pollId: pollId,
      vote: vote,
      timestamp: new Date().toISOString()
    });
    console.log("Interaction recorded:", response);
    return response;
  } catch (error) {
    console.error("Error recording interaction:", error);
    return null;
  }
}
```

